import{_ as a,o,c as d,af as c}from"./chunks/framework.zl0XNxp1.js";const p=JSON.parse('{"title":"重庆 - 2025","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/travel_record/ChongQing.md","filePath":"2_articles/travel_record/ChongQing.md","lastUpdatedText":"2025-08-13 22:21:13"}'),t={name:"2_articles/travel_record/ChongQing.md"};function r(i,e,l,n,h,_){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="重庆-2025" tabindex="-1">重庆 - 2025 <a class="header-anchor" href="#重庆-2025" aria-label="Permalink to &quot;重庆 - 2025&quot;">​</a></h1><h2 id="_2月14日-2月17日-☀️" tabindex="-1">2月14日 - 2月17日 ☀️ <a class="header-anchor" href="#_2月14日-2月17日-☀️" aria-label="Permalink to &quot;2月14日 - 2月17日 ☀️&quot;">​</a></h2><blockquote><p>2025情人节之旅！</p></blockquote><h3 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h3><p>大四保研结束后，在上海实习的某一天晚上，坐在地铁上回家时突然发现我们好像从来没有在冬天一起出去旅游过，因为异地只能在五一和国庆出去，查了下日历惊奇的发现寒假开学前几天刚好是情人节，在地铁上给黛黛发了消息，没想到和她不谋而合哈哈，于是火速订了机票，决定在情人节这天，去我们一直想去的城市——<code>山城重庆</code>，度过我们的第一次冬季旅行！</p><h3 id="_2月14日" tabindex="-1">2月14日 <a class="header-anchor" href="#_2月14日" aria-label="Permalink to &quot;2月14日&quot;">​</a></h3><p>情人节当天，我们在老家一大早打了车出发机场，这也是黛黛第一次坐飞机。下午五点到达重庆江北机场，拍了重庆特有的小黄车出租，我们酒店定在了<code>洪崖洞</code>附近，结果因为重庆特殊的地形，导航没发现酒店就在<code>魁星楼</code>上，本来坐地铁能从机场直达酒店，结果打车堵到晚上才到酒店，到酒店楼下，我们俩饿的要死，买了两根烤肠先垫垫肚子，一问价格说两根十块，初到重庆，还以为是重庆物价很高加上太饿就直接付款了没放在心上，到了酒店回想一下，好像是因为重庆人的口音，老板说的两根sei块，我以为是十块😇......放好行李后，出去参观了一下重庆站在一楼，实际是21楼的壮丽景象，参观完第二天才知道原来酒店就在魁星楼，而且对面就是地铁站。之后去了某📕上很火的<code>莲姐火锅</code>，大晚上又被重庆地形绕晕，感觉导航完全没用，因为它也不知道我们到底是在地下还是天桥上，先是不小心上了洪崖洞，又是绕了半天迷路了，好不容易找到，又排了很久很久的队，饿的不行了才吃到了火锅，后来因为在重庆到处都是火锅味，导致我们后面不管在哪个城市，只要闻到川味火锅，直接想吐......吃完火锅后，在洪崖洞上绕了半天才绕回了魁星楼，买了<code>一只酸奶牛</code>后回了酒店。</p><h3 id="_2月15日" tabindex="-1">2月15日 <a class="header-anchor" href="#_2月15日" aria-label="Permalink to &quot;2月15日&quot;">​</a></h3><p>第二天的早上，我们起了大早赶地铁，因为约了黛黛一直想去的<code>重庆动物园</code>，在地铁上看到了重庆的山城景象，是真的绕呀！然后在虫洞待了一早上看能猫，中午吃了重庆的<code>豆花饭</code>，表示完全吃不惯，吃完后去了<code>涂鸦一条街</code>，暴走几万步给黛黛拍了易烊千玺的雕塑像，找路人帮我们拍了我们的第一张旅行拍立得，之后实在累的不行坐了重庆的小三轮去地铁站，路上拍了非常有生活气息的视频，就此埋下要买Pocket3的想法哈哈，晚上去了<code>观音桥</code>和<code>鹅岭二厂</code>，打卡了重庆的网红地标显示屏，一直拍到大晚上才回酒店。</p><h3 id="_2月16日" tabindex="-1">2月16日 <a class="header-anchor" href="#_2月16日" aria-label="Permalink to &quot;2月16日&quot;">​</a></h3><p>第三天中午去了<code>解放碑</code>，吃了重庆辣子鸡，表示没鸡全是辣椒🤗，下午坐地铁去了<code>人民大礼堂</code>和<code>三峡博物馆</code>，地铁上两个憨货一直在地铁最前面看人家开地铁，之后暴走一下午，从博物馆出来腿都断了，然后又坐地铁去了<code>下浩里</code>，又是暴走+爬坡，晚上实在饿得不行吃了碗<code>重庆小面</code>后又打车回了洪崖洞，这才是第一次正式游览洪崖洞，人巨多无比，完全没法游览，就在洪崖洞又拍了一组照片后回了酒店。</p><h3 id="_2月17日" tabindex="-1">2月17日 <a class="header-anchor" href="#_2月17日" aria-label="Permalink to &quot;2月17日&quot;">​</a></h3><p>最后一天起来收拾好了行李，又去解放碑的苍蝇小馆吃了重庆当地特色菜，逛了一圈后又去了<code>罗汉寺</code>，又在周边随便逛了逛后就返回酒店拿行李，送黛黛去机场回学校，我也要坐火车回学校了，这次分别我们谁都没有哭哈哈，因为这是我们最后一次的异地旅行啦，所以我的重庆旅游文案是：<code>再也不用为了见面而旅行，而是我们一起出发去旅行！</code></p>',13)])])}const u=a(t,[["render",r]]);export{p as __pageData,u as default};
